from flask import Flask, request

app = Flask(__name__)

@app.route("/")
def index():
    return mongo

@app.route("/add", methods=["POST"])
def add():
    title = request.form["title"]
    about = request.form["about"]

    item = {"title": title, "about": about}
    db.items.insert_one(item)
    return 'Item added! <a href="/review">Review submissions</a>'

@app.route("/review")
def review():
    items = db.items.find()
    items_table = [
        '<table>',
        '<tr><th>Title</th><th>About</th></tr>',
    ]
    for item in items:
        # Vulnerability: user input is interpolated directly into HTML without escaping
        items_table.append('<tr><td>{}</td><td>{}</td></tr>'.format(escape(item["title"]), escape(item["about"])))
    items_table.append('</table>')

    return ' '.join(items_table)

if __name__ == "__main__":
    app.run()
